begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
set local timezone='Pacific/Honolulu';
insert into auth.users(id,instance_id,aud,role,email) select ('ab220000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','notification-'||n||'@example.invalid' from generate_series(1,5)n;
insert into public.staff_users(user_id,role) values('ab220000-0000-4000-8000-000000000001','admin'),('ab220000-0000-4000-8000-000000000002','office'),('ab220000-0000-4000-8000-000000000003','technician'),('ab220000-0000-4000-8000-000000000004','technician');
insert into public.customers(id,name) values('cc220000-0000-4000-8000-000000000001','SQLTEST Klient powiadomień');
insert into public.locations(id,customer_id,address,city) values('ca220000-0000-4000-8000-000000000001','cc220000-0000-4000-8000-000000000001','Adres','Miasto');
insert into public.installations(id,location_id,type) values('cb220000-0000-4000-8000-000000000001','ca220000-0000-4000-8000-000000000001','split');
insert into public.staff_customer_assignments(user_id,customer_id) values('ab220000-0000-4000-8000-000000000003','cc220000-0000-4000-8000-000000000001'),('ab220000-0000-4000-8000-000000000004','cc220000-0000-4000-8000-000000000001');
insert into public.customer_memberships(user_id,customer_id) values('ab220000-0000-4000-8000-000000000005','cc220000-0000-4000-8000-000000000001');
insert into public.service_tickets(id,installation_id,customer_id,subject,description,priority,assigned_to) values('ce220000-0000-4000-8000-000000000001','cb220000-0000-4000-8000-000000000001','cc220000-0000-4000-8000-000000000001','Awaria SQLTEST','PRIVATE SERVICE DESCRIPTION','high','ab220000-0000-4000-8000-000000000003');
insert into public.maintenance_plans(id,installation_id,interval_months,next_due_on,title) values('cf220000-0000-4000-8000-000000000001','cb220000-0000-4000-8000-000000000001',12,(now() at time zone 'Europe/Warsaw')::date+10,'Przegląd SQLTEST');
create function pg_temp.task(n integer,who integer default 3,delta integer default 0,state text default 'todo') returns jsonb language sql as $$select public.save_crm_record('cc220000-0000-4000-8000-000000000001','tasks',('df220000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,null,jsonb_build_object('title',case when who=4 then 'HIDDEN OTHER TASK' else 'Kontakt SQLTEST '||n end,'description','PRIVATE TASK DESCRIPTION','kind','follow_up','dueOn',to_char((now() at time zone 'Europe/Warsaw')::date+delta,'YYYY-MM-DD'),'assigneeId','ab220000-0000-4000-8000-'||lpad(who::text,12,'0'),'contactId',null,'state',state,'result',''))$$;
create function pg_temp.first_id() returns uuid language sql as $$select (public.list_my_notifications('all','tasks')->'items'->0->>'id')::uuid$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','ab220000-0000-4000-8000-000000000002',true);
select pg_temp.task(1),pg_temp.task(2,3,-1),pg_temp.task(3,3,1),pg_temp.task(4,3,-2,'done'),pg_temp.task(5,4,-1);
select set_config('request.jwt.claim.sub','ab220000-0000-4000-8000-000000000003',true);
select is(public.my_notification_preferences()->>'version',null::text,'Default preferences are not persisted by read');
select is(public.list_my_notifications()->>'total','0','Read does not synthesize history');
select is(public.sync_my_notifications()->>'added','4','Only own due tasks, assigned urgent service and upcoming plan collected');
select is(public.sync_my_notifications()->>'added','0','Repeat synchronization deduplicated');
select is(public.list_my_notifications()->>'total','4','History contains registered reminders');
select is(public.list_my_notifications()->>'unread','4','Initial reminders unread');
select ok(public.list_my_notifications()::text !~ 'PRIVATE|HIDDEN|description|result|costCents|email','Metadata projection excludes private descriptions and other tasks');
select is(public.list_my_notifications('all','tasks')->>'total','2','Category filter');
select is((public.list_my_notifications('all','tasks')->'items'->0->>'href') like '%tab=tasks&filter=all&page=%#crm-%',true,'Task link resolves into paginated client tasks');
select is(public.mark_my_notification(pg_temp.first_id(),0,true)->>'version','1','Mark read increments version');
select is(public.mark_my_notification(pg_temp.first_id(),0,true)->>'version','1','Read retry is idempotent');
select is(public.list_my_notifications('read','tasks')->>'total','1','Read filter');
select is(public.list_my_notifications('unread','tasks')->>'total','1','Unread filter');
select throws_ok($$select public.mark_my_notification(pg_temp.first_id(),0,false)$$,'40001',null,'Stale reverse state denied');
select is(public.mark_my_notification(pg_temp.first_id(),1,false)->>'version','2','Read state reversible');
select is(public.save_notification_preferences(null,false,true,true)->>'version','0','Own preferences saved');
select is(public.save_notification_preferences(null,false,true,true)->>'version','0','Initial preferences retry safe');
reset role;
update public.crm_tasks set fields=jsonb_set(fields,'{dueOn}',to_jsonb(to_char((now() at time zone 'Europe/Warsaw')::date-3,'YYYY-MM-DD'))) where id='df220000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.sync_my_notifications()->>'added','0','Disabled category stops new registrations');
select is(public.list_my_notifications('all','tasks')->>'total','2','Disabling does not remove history');
select is(public.save_notification_preferences(0,true,true,true)->>'version','1','Re-enable category');
select throws_ok($$select public.save_notification_preferences(0,false,false,false)$$,'40001',null,'Stale preferences rejected');
select is(public.sync_my_notifications()->>'added','1','New deadline collected after re-enable');
reset role;
update public.crm_tasks set fields=jsonb_set(fields,'{state}','"done"') where id in('df220000-0000-4000-8000-000000000001','df220000-0000-4000-8000-000000000002');
update public.service_tickets set status='closed' where id='ce220000-0000-4000-8000-000000000001';
update public.maintenance_plans set active=false where id='cf220000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.sync_my_notifications()->>'added','0','Resolved sources do not emit further reminders');
select is(public.list_my_notifications()->>'total','5','Resolved reminders remain in history');
select ok(not exists(select 1 from jsonb_array_elements(public.list_my_notifications()->'items')n where (n->>'current')::boolean),'Resolved reminders no longer current');
reset role;
create temp table notification_target as select id from public.app_notifications where user_id='ab220000-0000-4000-8000-000000000003' limit 1;
grant select on notification_target to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','ab220000-0000-4000-8000-000000000004',true);
select is(public.list_my_notifications()->>'total','0','Other technician has separate history');
select throws_ok($$select public.mark_my_notification((select id from notification_target),0,true)$$,'42501',null,'Other actor cannot mark own colleague notification');
select is(public.my_notification_preferences()->>'tasks','true','Preferences isolated by actor');
reset role;
delete from public.staff_customer_assignments where user_id='ab220000-0000-4000-8000-000000000003';
set local role authenticated;
select set_config('request.jwt.claim.sub','ab220000-0000-4000-8000-000000000003',true);
select is(public.list_my_notifications()->>'total','0','Revoked customer access hides historical titles and counts');
select throws_ok($$select public.mark_my_notification((select id from notification_target),0,true)$$,'42501',null,'Revoked access also denies marking history');
select throws_ok($$select * from public.app_notifications$$,'42501',null,'Ledger has no direct access');
select throws_ok($$select * from public.notification_preferences$$,'42501',null,'Preference table has no direct access');
select throws_ok($$select * from public.notification_sources()$$,'42501',null,'Private source projection not executable directly');
select set_config('request.jwt.claim.sub','ab220000-0000-4000-8000-000000000005',true);
select throws_ok($$select public.list_my_notifications()$$,'42501',null,'Client denied internal history');
select throws_ok($$select public.sync_my_notifications()$$,'42501',null,'Client denied collection');
select throws_ok($$select public.save_notification_preferences(null,true,true,true)$$,'42501',null,'Client denied internal preferences');
reset role;
insert into public.account_access(user_id,blocked) values('ab220000-0000-4000-8000-000000000003',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','ab220000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.list_my_notifications()$$,'42501',null,'Blocked staff denied');
select set_config('request.jwt.claim.sub','ab220000-0000-4000-8000-000000000002',true);
select pg_temp.task(n,4,-1) from generate_series(100,300)n;
select set_config('request.jwt.claim.sub','ab220000-0000-4000-8000-000000000004',true);
select is(public.sync_my_notifications()->>'added','200','Registration batch bounded to 200');
select is(public.sync_my_notifications()->>'added','2','Next synchronization drains remaining candidates, not first 200 again');
select is(public.sync_my_notifications()->>'added','0','All batches deduplicated');
select is(jsonb_array_length(public.list_my_notifications()->'items'),25,'History page bounded to 25');
select is(jsonb_array_length(public.list_my_notifications('all','all',2)->'items'),25,'Second history page available');
select throws_ok($$select public.list_my_notifications('all','all',0)$$,'22023',null,'Invalid page denied');
reset role;
update public.customers set archived_at=now() where id='cc220000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.list_my_notifications()->>'total','0','Archived customer excluded from history and counts');
reset role;
set local role anon;
select throws_ok($$select public.list_my_notifications()$$,'42501',null,'Anonymous denied');
select * from finish();
rollback;
